&lt;div class=&quot;css-4ioo53-EditorContainer e1ge5hpl1&quot; data-automation-id=&quot;richTextEditor&quot; data-metadata-id=&quot;56$309310&quot; data-uxi-widget-editable=&quot;false&quot;&gt;
&lt;div class=&quot;css-1v6ili8-TextEditorContainer eg1t6ed0&quot; data-automation-id=&quot;richTextContent&quot;&gt;
