&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The opportunity&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, you’ll find an environment designed for continuous learning, meaningful impact, and professional growth. Whether you&#39;re pioneering new digital solutions, challenging conventional thinking or building the next generation of customer experiences, your work will help transform industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are proud of:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;The work we do and the innovation we drive&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our values of share, care &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;nd dare&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;A workplace culture that fosters creativity, diversity and autonomy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/about/offices/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our borderless, global framework, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;which enables &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;seamless collaboration&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The role&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;As a &lt;strong&gt;Senior QA engineer &lt;/strong&gt;&amp;nbsp;you are passionate about experience innovation and eager to push the boundaries of what’s possible. You bring&lt;strong&gt; 5+ YEARS&lt;/strong&gt;&amp;nbsp;of experience, a growth mindset and a drive to make a lasting impact.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will thrive in this role if you are:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A curious problem solver who challenges the status quo&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A collaborator who values teamwork and knowledge-sharing&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excited by the intersection of technology, creativity and data&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experienced in Agile methodologies and consulting (a plus)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Role responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead end-to-end QA activities for CMS(Sitecore) and web platforms .&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Manage functional, regression, UAT, accessibility, analytics, and performance testing.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Design, implement, and maintain automation frameworks using Playwright/Typescript.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Integrate automation with CI/CD pipelines (GitHub Actions).&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Support content migration and rollout validations.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Coordinate with Dev, BA, DevOps, and business stakeholders.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Drive defect triage, root cause analysis, and quality improvements.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Mentor and guide junior QA team members.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Prepare QA reports, dashboards, and release readiness documentation.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Must have qualifications&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;To be considered for this role, you must meet the following essential qualifications:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of experience in Software Testing and Quality Assurance.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Strong experience in CMS testing (Sitecore preferred).&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Hands-on experience with Playwright.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Proficiency in TypeScript/JavaScript.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience with Azure DevOps and GitHub.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Knowledge of Agile/Scrum methodologies.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Strong understanding of accessibility, performance, and analytics testing.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience in cross-browser and multi-device testing.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Excellent defect management and reporting skills.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nice to have qualifications &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience in large-scale enterprise website rollouts.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Exposure to performance tools (BlazeMeter, Lighthouse).&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW105898609 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW105898609 BCX0&quot;&gt;If you do not meet all the listed qualifications or have gaps in your experience, we still encourage you to apply. At Valtech, we recognize that talent comes in many forms, and we value diverse perspectives and a willingness to learn.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW105898609 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Commitment to reaching all kinds of people&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We design experiences that work for all kinds of people - and that starts with our own teams. At Valtech, we’re intentional about building an inclusive culture where everyone feels supported to grow, thrive and achieve their goals. No matter your background, you belong here. &lt;/span&gt;&lt;a href=&quot;https://www.valtech.com/about/diversity-inclusion/&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Explore our Diversity &amp;amp; Inclusion site&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to see how we’re creating a more equitable Valtech for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The benefits &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a &lt;strong&gt;Full time&lt;/strong&gt; position based in &lt;strong&gt;Bengaluru.&lt;/strong&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Beyond a competitive compensation package, we offer:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexibility, with remote and hybrid work options (country-dependent)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Career advancement, with international mobility and professional development programs&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Learning and development, with access to cutting-edge tools, training and industry experts&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our benefits are tailored to each location. Your Talent Partner will provide full details during the hiring process.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your application process&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Once you apply, our Talent Acquisition team will review your application. Your CV should cover key information on relevant experiences and expertise. We do not require information such as age, gender, marital status, or a headshot in your application. We review all candidates based on skills, experience, and potential.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️ Beware of recruitment fraud! Only engage with official Valtech email addresses ending&amp;nbsp;in @valtech.com.&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are committed to inclusion and accessibility. If you need reasonable accommodations during the interview process, please either indicate it in your application or let your Talent Partner know.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About Valtech&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech is the experience innovation company that exists to unlock a better way to experience the world. By blending crafts, categories, and cultures, we help brands unlock new value in an increasingly digital world.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the intersection of data, AI, creativity, and technology, we drive transformation for leading organizations, including L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, we don’t just talk about transformation. We make it happen. Our people are the heart of our success, and we foster a workplace where everyone has the support to thrive, grow and innovate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you ready to create what’s next? Join us.&lt;/span&gt;&lt;/p&gt;

startx-valtech:greenhouse:4863316101.descriptionHtml:
&lt;p&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;Why Valtech?&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;We’re&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;the&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;experience&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; innovation company &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;- &lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW246265904 BCX0&quot;&gt;a&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; trusted partner&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; to the world’s most recognized brands. To our people we offer &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;growth opportunities, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;a &lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;values&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;-driven culture, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;international &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;careers&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; and the chance to shape the future of experience.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP CommentStart SCXW246265904 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The opportunity&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, you’ll find an environment designed for continuous learning, meaningful impact, and professional growth. Whether you&#39;re pioneering new digital solutions, challenging conventional thinking or building the next generation of customer experiences, your work will help transform industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are proud of:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;The work we do and the innovation we drive&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our values of share, care &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;nd dare&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;A workplace culture that fosters creativity, diversity and autonomy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/about/offices/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our borderless, global framework, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;which enables &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;seamless collaboration&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The role&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p data-start=&quot;846&quot; data-end=&quot;1066&quot;&gt;As a Senior Data Analyst, you are passionate about data-driven transformation and eager to push the boundaries of what’s possible. You bring 5+ years of experience, a growth mindset and a drive to make a lasting impact.&lt;/p&gt;
&lt;p data-start=&quot;1068&quot; data-end=&quot;1109&quot;&gt;You will thrive in this role if you are:&lt;/p&gt;
&lt;ul data-start=&quot;1111&quot; data-end=&quot;1557&quot;&gt;
&lt;li data-section-id=&quot;18vx8di&quot; data-start=&quot;1111&quot; data-end=&quot;1205&quot;&gt;A curious problem solver who can translate business needs into actionable data requirements&lt;/li&gt;
&lt;li data-section-id=&quot;oryr77&quot; data-start=&quot;1206&quot; data-end=&quot;1294&quot;&gt;A self-driven professional who can work autonomously and proactively after onboarding&lt;/li&gt;
&lt;li data-section-id=&quot;1c36844&quot; data-start=&quot;1295&quot; data-end=&quot;1390&quot;&gt;A collaborator who values teamwork and knowledge-sharing across technical and business teams&lt;/li&gt;
&lt;li data-section-id=&quot;19n92fn&quot; data-start=&quot;1391&quot; data-end=&quot;1468&quot;&gt;Excited by the intersection of data, technology and operational excellence&lt;/li&gt;
&lt;li data-section-id=&quot;1lubykk&quot; data-start=&quot;1469&quot; data-end=&quot;1557&quot;&gt;Experienced in Agile methodologies and working within complex enterprise environments&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Role responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-section-id=&quot;1aq0110&quot; data-start=&quot;1585&quot; data-end=&quot;1690&quot;&gt;Gather, analyze and document business and data requirements from stakeholders across enterprise domains&lt;/li&gt;
&lt;li data-section-id=&quot;1ixaa9y&quot; data-start=&quot;1691&quot; data-end=&quot;1773&quot;&gt;Manage and prioritize incoming data-related requests, tickets and business needs&lt;/li&gt;
&lt;li data-section-id=&quot;4a8b2c&quot; data-start=&quot;1774&quot; data-end=&quot;1886&quot;&gt;Translate business requirements into clear data requirements to support ingestion and transformation processes&lt;/li&gt;
&lt;li data-section-id=&quot;15fsoxg&quot; data-start=&quot;1887&quot; data-end=&quot;1984&quot;&gt;Support the development and expansion of enterprise-level data products and gold-layer datasets&lt;/li&gt;
&lt;li data-section-id=&quot;9lgrbi&quot; data-start=&quot;1985&quot; data-end=&quot;2121&quot;&gt;Collaborate with data architects, engineers and delivery leads to ensure alignment between business objectives and technical solutions&lt;/li&gt;
&lt;li data-section-id=&quot;vkdwhc&quot; data-start=&quot;2122&quot; data-end=&quot;2222&quot;&gt;Collect and document data quality rules, metadata and catalog descriptions for new data ingestions&lt;/li&gt;
&lt;li data-section-id=&quot;1etnsyn&quot; data-start=&quot;2223&quot; data-end=&quot;2327&quot;&gt;Work with governance and stewardship teams to support data lineage, quality and cataloging initiatives&lt;/li&gt;
&lt;li data-section-id=&quot;1e39ig1&quot; data-start=&quot;2328&quot; data-end=&quot;2413&quot;&gt;Facilitate communication between business stakeholders and technical delivery teams&lt;/li&gt;
&lt;li data-section-id=&quot;1quwynj&quot; data-start=&quot;2414&quot; data-end=&quot;2511&quot;&gt;Contribute to continuous improvement initiatives across data delivery and operational processes&lt;/li&gt;
&lt;li data-section-id=&quot;1dz9y5d&quot; data-start=&quot;2512&quot; data-end=&quot;2593&quot;&gt;Support Agile ceremonies, backlog refinement and workflow management activities&lt;/li&gt;
&lt;li data-section-id=&quot;v8354e&quot; data-start=&quot;2594&quot; data-end=&quot;2712&quot;&gt;Participate in cross-functional discussions related to data modeling, transformation logic and platform capabilities&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Must have qualifications&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p data-start=&quot;2743&quot; data-end=&quot;2829&quot;&gt;To be considered for this role, you must meet the following essential qualifications:&lt;/p&gt;
&lt;ul data-start=&quot;2831&quot; data-end=&quot;3499&quot;&gt;
&lt;li data-section-id=&quot;1iqozti&quot; data-start=&quot;2831&quot; data-end=&quot;2922&quot;&gt;5+ years of experience in data analysis, business analysis or data-focused delivery roles&lt;/li&gt;
&lt;li data-section-id=&quot;lylk9m&quot; data-start=&quot;2923&quot; data-end=&quot;3019&quot;&gt;Experience gathering and documenting business and data requirements in enterprise environments&lt;/li&gt;
&lt;li data-section-id=&quot;1xpwjv&quot; data-start=&quot;3020&quot; data-end=&quot;3095&quot;&gt;Strong understanding of modern data platforms and data lifecycle concepts&lt;/li&gt;
&lt;li data-section-id=&quot;dhh2ov&quot; data-start=&quot;3096&quot; data-end=&quot;3166&quot;&gt;Experience working with Agile methodologies such as SCRUM and Kanban&lt;/li&gt;
&lt;li data-section-id=&quot;3kll78&quot; data-start=&quot;3167&quot; data-end=&quot;3283&quot;&gt;Familiarity with data warehousing concepts, including layered architectures such as bronze, silver and gold models&lt;/li&gt;
&lt;li data-section-id=&quot;14rq8bo&quot; data-start=&quot;3284&quot; data-end=&quot;3401&quot;&gt;Experience collaborating with cross-functional teams including data engineers, architects and business stakeholders&lt;/li&gt;
&lt;li data-section-id=&quot;zkvt1m&quot; data-start=&quot;3402&quot; data-end=&quot;3457&quot;&gt;Strong analytical thinking and problem-solving skills&lt;/li&gt;
&lt;li data-section-id=&quot;u3xgja&quot; data-start=&quot;3458&quot; data-end=&quot;3499&quot;&gt;Excellent command of English (C2 level)&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nice to have qualifications &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-section-id=&quot;qub0y2&quot; data-start=&quot;3535&quot; data-end=&quot;3609&quot;&gt;Experience working with Databricks or similar cloud-based data platforms&lt;/li&gt;
&lt;li data-section-id=&quot;16jkeqz&quot; data-start=&quot;3610&quot; data-end=&quot;3669&quot;&gt;Familiarity with data governance and data quality tooling&lt;/li&gt;
&lt;li data-section-id=&quot;kgbqnz&quot; data-start=&quot;3670&quot; data-end=&quot;3707&quot;&gt;Experience with Jira and Confluence&lt;/li&gt;
&lt;li data-section-id=&quot;qpfkbd&quot; data-start=&quot;3708&quot; data-end=&quot;3776&quot;&gt;Understanding of DBT, Airflow and modern transformation frameworks&lt;/li&gt;
&lt;li data-section-id=&quot;b45u1g&quot; data-start=&quot;3777&quot; data-end=&quot;3838&quot;&gt;Knowledge of conceptual and logical data modeling practices&lt;/li&gt;
&lt;li data-section-id=&quot;1ouvr2m&quot; data-start=&quot;3839&quot; data-end=&quot;3905&quot;&gt;Experience in operational or transportation-related environments&lt;/li&gt;
&lt;li data-section-id=&quot;cz8pyp&quot; data-start=&quot;3906&quot; data-end=&quot;3962&quot;&gt;Strong communication and stakeholder management skills&lt;/li&gt;
&lt;li data-section-id=&quot;8wigeu&quot; data-start=&quot;3963&quot; data-end=&quot;4031&quot;&gt;Ability to work independently in fast-paced, evolving environments&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW105898609 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW105898609 BCX0&quot;&gt;If you do not meet all the listed qualifications or have gaps in your experience, we still encourage you to apply. At Valtech, we recognize that talent comes in many forms, and we value diverse perspectives and a willingness to learn.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW105898609 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;br&gt;Commitment to reaching all kinds of people&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We design experiences that work for all kinds of people - and that starts with our own teams. At Valtech, we’re intentional about building an inclusive culture where everyone feels supported to grow, thrive and achieve their goals. No matter your background, you belong here. &lt;/span&gt;&lt;a href=&quot;https://www.valtech.com/about/diversity-inclusion/&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Explore our Diversity &amp;amp; Inclusion site&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to see how we’re creating a more equitable Valtech for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;br&gt;The benefits &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a&amp;nbsp;position based in Portugal.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Beyond a competitive compensation package, we offer:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexibility, with remote and hybrid work options (country-dependent)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Career advancement, with international mobility and professional development programs&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Learning and development, with access to cutting-edge tools, training and industry experts&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our benefits are tailored to each location. Your Talent Partner will provide full details during the hiring process.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong style=&quot;font-size: 14px;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your application process&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Once you apply, our Talent Acquisition team will review your application. Your CV should cover key information on relevant experiences and expertise. We do not require information such as age, gender, marital status, or a headshot in your application. We review all candidates based on skills, experience, and potential.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️ Beware of recruitment fraud!&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are committed to inclusion and accessibility. If you need reasonable accommodations during the interview process, please either indicate it in your application or let your Talent Partner know.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About Valtech&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech is the experience innovation company that exists to unlock a better way to experience the world. By blending crafts, categories, and cultures, we help brands unlock new value in an increasingly digital world.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the intersection of data, AI, creativity, and technology, we drive transformation for leading organizations, including L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, we don’t just talk about transformation. We make it happen. Our people are the heart of our success, and we foster a workplace where everyone has the support to thrive, grow and innovate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you ready to create what’s next? Join us.&lt;/span&gt;&lt;/p&gt;

startx-valtech:greenhouse:4893632101.descriptionHtml:
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Opportunité&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;À Valtech, vous trouverez un environnement propice à l’apprentissage continu, à l’impact concret et à la croissance professionnelle. Que vous développiez de nouvelles solutions digitales, remettiez en question les idées reçues ou construisiez la prochaine génération d’expériences client, votre travail contribuera à transformer les secteurs d&#39;activité.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nous&amp;nbsp;sommes&amp;nbsp;fiers&amp;nbsp;de:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Notre travail et&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;l&#39;innovation&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;que nous&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;encourageons&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Nos&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;valeurs&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;: « share, dare, care »&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Une culture&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;d&#39;entreprise&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;qui&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;favorise&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;la&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;créativité&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;, la&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;diversité&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;et&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;l&#39;autonomie&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/about/offices/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Notre structure&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;mondiale&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;sans&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;frontières&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;, qui&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;permet&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;une&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;collaboration&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;fluide&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;La maîtrise de l&#39;anglais est requise, car le rôle implique des communications régulières avec des clients et des collègues situés à l&#39;extérieur du Québec.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Rôle&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;En tant qu&#39;ingénieur(e) en assurance qualité, vous êtes passionné(e) par la livraison d&#39;expériences numériques de haute qualité et désireux(se) d&#39;élargir vos compétences en tests automatisés. Vous apportez environ 3 ans ou plus d&#39;expérience pratique en tests automatisés et manuels, un état d&#39;esprit axé sur la croissance et la motivation de développer une expertise plus solide en assurance qualité, tout en ayant un impact significatif sur l&#39;équipe et le produit.&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Vous vous épanouirez dans ce rôle si vous êtes une&amp;nbsp;personne:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Curieuse et capable de&amp;nbsp;résoudre&amp;nbsp;des&amp;nbsp;problématiques&amp;nbsp;complexes et de&amp;nbsp;remettre&amp;nbsp;en&amp;nbsp;question les pratiques&amp;nbsp;établies&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valorisant&amp;nbsp;la collaboration et le partage des&amp;nbsp;connaissances&amp;nbsp;au sein&amp;nbsp;d’une&amp;nbsp;équipe&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Enthousiaste&amp;nbsp;à&amp;nbsp;l’idée&amp;nbsp;de&amp;nbsp;travailler&amp;nbsp;à&amp;nbsp;l’intersection&amp;nbsp;de la&amp;nbsp;technologie, de la&amp;nbsp;créativité&amp;nbsp;et des données&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ayant&amp;nbsp;une&amp;nbsp;expérience&amp;nbsp;avérée&amp;nbsp;des pratiques&amp;nbsp;agiles&amp;nbsp;et du conseil (un plus)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Responsabilités&amp;nbsp;du poste&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p class=&quot;font-claude-response-body break-words whitespace-normal&quot;&gt;Participer aux initiatives internes pour soutenir et développer notre pratique dans son ensemble. Être un(e) champion(ne) des meilleures pratiques en matière de qualité.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Qualifications&amp;nbsp;requises&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p class=&quot;font-claude-response-body break-words whitespace-normal&quot;&gt;Pour être considéré(e) pour ce poste, vous devez satisfaire aux qualifications essentielles suivantes :&lt;/p&gt;
&lt;ul class=&quot;[li_&amp;amp;]:mb-0 [li_&amp;amp;]:mt-1 [li_&amp;amp;]:gap-1 [&amp;amp;:not(:last-child)_ul]:pb-1 [&amp;amp;:not(:last-child)_ol]:pb-1 list-disc flex flex-col gap-1 pl-8 mb-3&quot;&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;3 ans ou plus d&#39;expérience dans la rédaction de tests automatisés et manuels ou dans le développement de fonctionnalités, incluant, sans s&#39;y limiter, la rédaction et l&#39;exécution de tests pour des applications web ou mobiles, des tests automatisés et des tests d&#39;API automatisés.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience dans le développement de tests automatisés en JavaScript et TypeScript.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience en automatisation AQ, de préférence en automatisation de bout en bout (E2E) avec Playwright, Selenium, Cypress, Appium ou des outils similaires.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Compétences analytiques et capacité à présenter l&#39;information de manière logique et bien organisée.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience de travail dans des environnements agiles/Scrum.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Solides compétences en communication claire et en négociation en français et en anglais.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Personne autonome et très motivée, joueur(se) d&#39;équipe qui travaille bien au sein d&#39;équipes interfonctionnelles.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Bilan démontré de développement de relations solides et positives avec l&#39;équipe de développement logiciel, notamment les développeurs et les analystes d&#39;affaires.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Solide expérience avec les outils de gestion de projets (JIRA, Azure DevOps ou similaires).&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience dans différents types de tests (boîte noire, boîte blanche, régression, détection de fumée, fonctionnels et non fonctionnels).&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience dans la rédaction de tests d&#39;interface utilisateur de bout en bout.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Qualifications&amp;nbsp;souhaitées&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience dans la rédaction de tests d&#39;API et d&#39;intégration avec l&#39;utilisation de cadres de simulation (mocking frameworks).&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Bonne compréhension des structures XML et JSON.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience de base dans la création de tests automatisés pour les API à l&#39;aide de RestAssured, RestSharp, Postman ou GraphQL.&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Expérience dans les tests d&#39;applications mobiles à l&#39;aide d&#39;émulateurs et d&#39;outils de tests en nuage (Browserstack, Crossbrowsertesting, etc.).&lt;/li&gt;
&lt;li class=&quot;font-claude-response-body whitespace-normal break-words pl-2&quot;&gt;Baccalauréat en informatique, en mathématiques ou dans un domaine connexe.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Si vous ne possédez pas toutes les qualifications mentionnées ou si vous avez des lacunes dans votre parcours, nous vous encourageons à postuler. À&amp;nbsp;Valtech, nous reconnaissons la richesse des talents et valorisons la pluralité des perspectives ainsi que la soif d’apprendre.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Engagement pour&amp;nbsp;l’inclusion&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nous concevons des expériences qui conviennent à toutes les personnes — et cela commence par nos équipes. À&amp;nbsp;Valtech, nous avons à cœur de bâtir une culture inclusive où chaque individu se sent soutenu pour grandir, s&#39;épanouir et atteindre ses objectifs. Quel que soit votre parcours, vous avez votre place.&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.valtech.com/about/diversity-inclusion/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Explorez notre site Diversité et Inclusion&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;pour&amp;nbsp;en savoir plus sur nos actions en faveur d’un&amp;nbsp;Valtech&amp;nbsp;plus équitable.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bénéfices&amp;nbsp;et&amp;nbsp;avantages&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p class=&quot;font-claude-response-body break-words whitespace-normal&quot;&gt;Il s&#39;agit d&#39;un poste à temps plein basé au Canada. La fourchette salariale offerte est de 69 000 $ CA à 86 000 $ CA annuellement, selon l&#39;expérience et le lieu de travail.&lt;/p&gt;
&lt;p data-start=&quot;116&quot; data-end=&quot;220&quot;&gt;Valtech offre un programme d’avantages sociaux complet, en vigueur après trois mois de service continu :&lt;/p&gt;
&lt;ul&gt;
&lt;li data-start=&quot;224&quot; data-end=&quot;521&quot;&gt;Un &lt;strong&gt;régime d’assurance complet&lt;/strong&gt;, avec la possibilité de choisir le module qui répond le mieux à vos besoins — Or, Argent ou Bronze. Selon le module sélectionné, l’employeur peut contribuer jusqu’à 80 % de votre couverture. Ce régime comprend des assurances invalidité &lt;strong&gt;de courte et de longue durée&lt;/strong&gt;.&lt;/li&gt;
&lt;li data-start=&quot;524&quot; data-end=&quot;873&quot;&gt;&lt;strong&gt;Dialogue via Sun Life&lt;/strong&gt; vous donne accès à des services de soins de santé virtuels, vous permettant de consulter un professionnel de la santé pour des urgences, des renouvellements d’ordonnance, et plus encore. Vous avez également accès au &lt;strong&gt;Programme d’aide aux employés et à leur famill&lt;/strong&gt;e, ainsi qu’à un programme complet de soutien en santé mentale.&lt;/li&gt;
&lt;li data-start=&quot;876&quot; data-end=&quot;1134&quot;&gt;Un &lt;strong&gt;Compte de dépenses&lt;/strong&gt; personnel de $500, pouvant être utilisé pour des remboursements de soins de santé, des abonnements au gym, des passes de transport en commun, des fournitures de bureau ou des contributions à votre REER par l’intermédiaire de Valtech.&lt;/li&gt;
&lt;li data-start=&quot;1137&quot; data-end=&quot;1489&quot;&gt;Un &lt;strong&gt;régime de retraite&lt;/strong&gt; dans lequel Valtech égalera 100% de vos contributions à votre REER par l’entremise d’un Régime de participation différée aux bénéfices (RPDB), jusqu’à un maximum de 4 %. Vous pouvez commencer à cotiser à votre REER immédiatement, et au RPDB après 3 mois. L’acquisition des droits du RPDB est complétée après 24 mois de service.&lt;/li&gt;
&lt;li data-start=&quot;1492&quot; data-end=&quot;1740&quot;&gt;L’accès à un &lt;strong&gt;programme de vacances flexibles&lt;/strong&gt; selon la politique de Valtech pour soutenir votre équilibre travail-vie personnelle, comprenant 5 jours disponibles pendant votre période de probation et un montant au prorata pour le reste de l’année.&lt;/li&gt;
&lt;li data-start=&quot;1743&quot; data-end=&quot;1845&quot;&gt;Un&lt;strong&gt; remboursement de technologie personnelle&lt;/strong&gt; — $30/mois offert à chaque employé dès le premier jour.&lt;/li&gt;
&lt;li data-start=&quot;1848&quot; data-end=&quot;2076&quot;&gt;Nous fermons durant les &lt;strong&gt;vacances d’hiver&lt;/strong&gt; et offrons des&lt;strong&gt; horaires flexibles &lt;/strong&gt;tout au long de l’année, afin que vous puissiez profiter des après-midi ensoleillées du vendredi — pourvu que vos heures hebdomadaires soient complétées.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Processus de&amp;nbsp;recrutement&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Une&amp;nbsp;fois&amp;nbsp;votre&amp;nbsp;candidature&amp;nbsp;envoyée,&amp;nbsp;notre&amp;nbsp;équipe Talent Acquisition&amp;nbsp;l’examinera&amp;nbsp;sous&amp;nbsp;quelques&amp;nbsp;jours. Si&amp;nbsp;vos&amp;nbsp;compétences&amp;nbsp;et&amp;nbsp;votre&amp;nbsp;expérience&amp;nbsp;correspondent au poste, nous vous&amp;nbsp;contacterons&amp;nbsp;pour les&amp;nbsp;prochaines&amp;nbsp;étapes.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Attention&amp;nbsp;aux fraudes : n’interagissez qu’avec des adresses&amp;nbsp;e-mail&amp;nbsp;officielles se terminant par @valtech.com.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nous&amp;nbsp;nous&amp;nbsp;engageons&amp;nbsp;en&amp;nbsp;faveur&amp;nbsp;de&amp;nbsp;l’inclusion&amp;nbsp;et de&amp;nbsp;l’accessibilité. Si vous&amp;nbsp;avez&amp;nbsp;besoin&amp;nbsp;d’un&amp;nbsp;aménagement&amp;nbsp;raisonnable&amp;nbsp;pendant le processus de&amp;nbsp;recrutement,&amp;nbsp;veuillez&amp;nbsp;l’indiquer&amp;nbsp;dans&amp;nbsp;votre&amp;nbsp;candidature&amp;nbsp;ou&amp;nbsp;en&amp;nbsp;informer&amp;nbsp;votre&amp;nbsp;Talent Partner.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;À&amp;nbsp;propos&amp;nbsp;de Valtech&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech est&amp;nbsp;une&amp;nbsp;entreprise&amp;nbsp;d’innovation&amp;nbsp;et&amp;nbsp;d’expérience&amp;nbsp;qui a pour vocation&amp;nbsp;d’offrir&amp;nbsp;une&amp;nbsp;meilleure&amp;nbsp;façon&amp;nbsp;d&#39;appréhender&amp;nbsp;le monde. En&amp;nbsp;combinant&amp;nbsp;expertises,&amp;nbsp;secteurs&amp;nbsp;et cultures, nous&amp;nbsp;aidons&amp;nbsp;les marques à&amp;nbsp;créer&amp;nbsp;de la&amp;nbsp;valeur&amp;nbsp;dans un monde de plus&amp;nbsp;en&amp;nbsp;plus digital.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;À&amp;nbsp;l’intersection&amp;nbsp;des données, de&amp;nbsp;l’IA, de la&amp;nbsp;créativité&amp;nbsp;et de la&amp;nbsp;technologie, nous&amp;nbsp;accompagnons&amp;nbsp;la transformation de&amp;nbsp;grandes&amp;nbsp;entreprises&amp;nbsp;telles&amp;nbsp;que&amp;nbsp;L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, et bien&amp;nbsp;d’autres.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;À Valtech, la transformation ne se&amp;nbsp;limite&amp;nbsp;pas aux&amp;nbsp;discours. Nous la&amp;nbsp;concrétisons. Nos&amp;nbsp;collaborateurs&amp;nbsp;sont&amp;nbsp;au&amp;nbsp;cœur&amp;nbsp;de&amp;nbsp;notre&amp;nbsp;succès, et nous&amp;nbsp;cultivons&amp;nbsp;un&amp;nbsp;environnement&amp;nbsp;où&amp;nbsp;chaque&amp;nbsp;talent&amp;nbsp;peut&amp;nbsp;s’épanouir,&amp;nbsp;évoluer&amp;nbsp;et&amp;nbsp;innover.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Prêt·e&amp;nbsp;à imaginer la&amp;nbsp;suite ?&amp;nbsp;Rejoignez-nous.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Conformément à la loi allemande sur l&#39;égalité de traitement et à son équivalent français, les offres d&#39;emploi doivent être publiées de manière non sexiste. Nous utilisons la mention pour préciser que ce poste est ouvert à tous les genres dans ces pays, même si le titre du poste lui-même peut être traduit ou interprété comme « masculin » en allemand ou en français.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

